param([string]$BaseUrl='http://localhost:14200')
$ErrorActionPreference='Stop';& "$PSScriptRoot/verify-merchant-fulfillment.ps1" -BaseUrl $BaseUrl;if(-not$?){throw 'Could not create shipped order'}
$session=[Microsoft.PowerShell.Commands.WebRequestSession]::new();$csrf=Invoke-RestMethod "$BaseUrl/api/auth/csrf" -WebSession $session;$headers=@{$csrf.headerName=$csrf.token};Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -WebSession $session -Headers $headers -ContentType application/json -Body '{"email":"demo@example.com","password":"demo-password","rememberMe":false}'|Out-Null
$orders=Invoke-RestMethod "$BaseUrl/api/purchase-orders" -WebSession $session;$shipped=$orders|Where-Object status -eq 'SHIPPED'|Select-Object -First 1;if(-not$shipped){throw 'Customer cannot see shipped order'}
$received=Invoke-RestMethod "$BaseUrl/api/purchase-orders/$($shipped.id)/receive" -Method Post -WebSession $session -Headers $headers -ContentType application/json -Body '{}';if($received.status-ne'RECEIVED'){throw 'Receive transition failed'};$item=$received.items[0]
$review=Invoke-RestMethod "$BaseUrl/api/order-items/$($item.id)/reviews" -Method Post -WebSession $session -Headers $headers -ContentType application/json -Body '{"rating":5,"comment":"Excellent learning product"}';if($review.rating-ne5){throw 'Review insert failed'}
try{Invoke-RestMethod "$BaseUrl/api/order-items/$($item.id)/reviews" -Method Post -WebSession $session -Headers $headers -ContentType application/json -Body '{"rating":4,"comment":"duplicate"}' -ErrorAction Stop|Out-Null;throw 'Duplicate review accepted'}catch{if([int]$_.Exception.Response.StatusCode-ne409){throw}}
try{Invoke-RestMethod "$BaseUrl/api/order-items/$($item.id)/reviews" -Method Post -WebSession $session -Headers $headers -ContentType application/json -Body '{"rating":6,"comment":"invalid"}' -ErrorAction Stop|Out-Null;throw 'Invalid rating accepted'}catch{if([int]$_.Exception.Response.StatusCode-ne400){throw}}
$products=Invoke-RestMethod "$BaseUrl/api/products" -WebSession $session;$product=$products|Where-Object id -eq $item.productId;if($product.reviewCount-lt1-or$product.averageRating-lt1){throw 'Product rating aggregate missing'}
Write-Host "Chapter 07 verification passed: SHIPPED -> RECEIVED, review unique, rating validation, aggregate=$($product.averageRating)" -ForegroundColor Green
